import { canonicalJson, valueHash } from './canonical.ts';

/**
 * Inputs for packages/contract/test-vectors/canonical-json.json. The Dart tests read that file, so
 * both implementations agree on every one; an API test fails if the file is stale.
 */
export const VECTORS_NOTE =
  'Generated by services/api/scripts/canonical-vectors.ts. Both implementations must reproduce every canonical string and hash.';

const inputs: unknown[] = [
  null,
  true,
  false,
  0,
  -0,
  1,
  -17,
  1.5,
  0.1,
  -1.5,
  // Where JavaScript switches between plain and exponent notation (Dart must match).
  1e20,
  1e21,
  1.5e300,
  0.000001,
  1e-7,
  1.5e-10,
  1.23e-18,
  1.0000000000000002,
  123456789012,
  9007199254740991,
  '',
  'Cough for 3 days',
  'quote " backslash \\ slash /',
  'line\nbreak\ttab\rreturn\bback\fform',
  '\u0000\u0001\u001f\u007f',
  'José Ñúñez · 日本 · emoji 🩺',
  'separators \u2028 \u2029 and DEL \u007f stay raw',
  [],
  [1, 'two', null, [3]],
  {},
  { b: 1, a: 2, A: 3, aa: 4, '': 5 },
  { nested: { z: [{ y: 1, x: 2 }], a: null } },
  { 'wound.length_cm': 4.2, 'wound.photos': ['p1', 'p2'], present: true },
];

export async function buildVectors() {
  const vectors = [];
  for (const input of inputs)
    vectors.push({ input, canonical: canonicalJson(input), sha256: await valueHash(input) });
  return vectors;
}

/** The file's exact text, so a stale copy is caught byte for byte. */
export async function vectorsFile(): Promise<string> {
  return `${JSON.stringify({ note: VECTORS_NOTE, vectors: await buildVectors() }, null, 2)}\n`;
}
